const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
document.body.classList.add('js-motion');
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}}),{threshold:.08});$$('.reveal').forEach(e=>observer.observe(e));
let scrollPending=false;window.addEventListener('scroll',()=>{if(scrollPending)return;scrollPending=true;requestAnimationFrame(()=>{const y=window.scrollY;$('#header').classList.toggle('scrolled',y>80);$('.progress').style.width=`${y/Math.max(1,document.documentElement.scrollHeight-innerHeight)*100}%`;if(!reduce&&y<innerHeight)$('.hero-image').style.transform=`translateY(${y*.15}px)`;scrollPending=false})},{passive:true});
$('.menu-toggle').addEventListener('click',()=>{const open=$('header nav').classList.toggle('open');$('.menu-toggle').setAttribute('aria-expanded',open);$('.menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation')});$$('header nav a').forEach(a=>a.addEventListener('click',()=>{$('header nav').classList.remove('open');$('.menu-toggle').setAttribute('aria-expanded','false')}));
const track=$('#car-track'),viewport=$('#gallery-window'),wheel=$('#steering-wheel');let target=0,current=0,angle=0,targetAngle=0,frame=0,filter='All';const visibleCards=()=>$$('.car-card').filter(c=>!c.hidden);const maxScroll=()=>Math.max(0,track.scrollWidth-viewport.clientWidth+parseFloat(getComputedStyle(document.body).fontSize)*0);const cardStep=()=>{const c=visibleCards()[0];return c?c.getBoundingClientRect().width+parseFloat(getComputedStyle(track).gap):0};
function animate(){const damping=reduce?1:.105;current+=(target-current)*damping;angle+=(targetAngle-angle)*damping;track.style.transform=`translate3d(${-current}px,0,0)`;wheel.style.setProperty('--wheel-angle',angle+'deg');const max=maxScroll(),value=max?Math.round(current/max*100):0;wheel.setAttribute('aria-valuenow',value);wheel.setAttribute('aria-valuetext',`${visibleCards().length===1?visibleCards()[0].dataset.type:visibleCards()[Math.min(visibleCards().length-1,Math.round(current/Math.max(1,cardStep())))].dataset.type} car category`);$('#gallery-counter').textContent=`${String(Math.min(visibleCards().length,Math.round(current/Math.max(1,cardStep()))+1)).padStart(2,'0')} / ${String(visibleCards().length).padStart(2,'0')}`;$('#prev-car').disabled=target<1;$('#next-car').disabled=target>=max-1;if(Math.abs(target-current)>.05||Math.abs(targetAngle-angle)>.05)frame=requestAnimationFrame(animate);else{current=target;angle=targetAngle;frame=0}}
function setTarget(x,rotation){target=Math.max(0,Math.min(maxScroll(),x));targetAngle=rotation??(maxScroll()?target/maxScroll()*240:0);if(!frame)frame=requestAnimationFrame(animate)}
$('#prev-car').addEventListener('click',()=>setTarget(target-cardStep()));$('#next-car').addEventListener('click',()=>setTarget(target+cardStep()));wheel.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','ArrowUp','ArrowDown','Home','End'].includes(e.key)){e.preventDefault();if(e.key==='Home')setTarget(0);else if(e.key==='End')setTarget(maxScroll());else setTarget(target+(['ArrowRight','ArrowUp'].includes(e.key)?1:-1)*cardStep()*.6)}});
let wheelDrag=null;const pointerAngle=e=>{const r=wheel.getBoundingClientRect();return Math.atan2(e.clientY-r.top-r.height/2,e.clientX-r.left-r.width/2)*180/Math.PI};wheel.addEventListener('pointerdown',e=>{wheel.setPointerCapture(e.pointerId);wheelDrag={last:pointerAngle(e)};e.preventDefault()});wheel.addEventListener('pointermove',e=>{if(!wheelDrag)return;let next=pointerAngle(e),delta=next-wheelDrag.last;if(delta>180)delta-=360;if(delta< -180)delta+=360;wheelDrag.last=next;setTarget(target+delta*Math.max(3,maxScroll()/240),Math.max(0,Math.min(240,targetAngle+delta)))});for(const event of ['pointerup','pointercancel','lostpointercapture'])wheel.addEventListener(event,()=>{wheelDrag=null});
let galleryDrag=null,moved=false;viewport.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;galleryDrag={x:e.clientX,y:e.clientY,start:target};moved=false});viewport.addEventListener('pointermove',e=>{if(!galleryDrag)return;const dx=e.clientX-galleryDrag.x;if(Math.abs(dx)>7){moved=true;setTarget(galleryDrag.start-dx)}});window.addEventListener('pointerup',()=>{galleryDrag=null});viewport.addEventListener('pointercancel',()=>galleryDrag=null);viewport.addEventListener('dragstart',e=>e.preventDefault());viewport.addEventListener('click',e=>{if(moved){e.preventDefault();moved=false}},true);window.addEventListener('resize',()=>setTarget(Math.min(target,maxScroll())));
function applyFilter(type){filter=type;$$('.car-card').forEach(c=>c.hidden=type!=='All'&&c.dataset.type!==type);$$('[data-filter]').forEach(b=>{const yes=b.dataset.filter===type;b.classList.toggle('active',yes);b.setAttribute('aria-pressed',yes)});setTarget(0);}
$$('[data-filter]').forEach(b=>b.addEventListener('click',()=>{applyFilter(b.dataset.filter);$('#body-style').value=b.dataset.filter}));$('#finder-form').addEventListener('submit',e=>{e.preventDefault();applyFilter($('#body-style').value);$('#search-status').textContent=`Your preferences: ${$('#budget').value} · ${filter==='All'?'All car styles':filter} · ${$('#transmission').value}. Explore below, then ask the team for matching stock.`;$('#collection').scrollIntoView({behavior:reduce?'instant':'smooth'});});setTarget(0);
let saved=[];try{saved=JSON.parse(localStorage.getItem('carChoiceSaved')||'[]');if(!Array.isArray(saved))saved=[]}catch{}function updateSaved(){saved=saved.filter(t=>['SUV','Sedan','Premium','Hatchback'].includes(t));$$('[data-save]').forEach(b=>{const yes=saved.includes(b.dataset.save);b.textContent=yes?'♥':'♡';b.setAttribute('aria-pressed',yes)});$('#saved-status').textContent=saved.length?`Your saved styles: ${saved.join(', ')}`:'Have a model in mind?';try{localStorage.setItem('carChoiceSaved',JSON.stringify(saved))}catch{}}let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}$$('[data-save]').forEach(b=>b.addEventListener('click',()=>{const type=b.dataset.save;const existed=saved.includes(type);saved=existed?saved.filter(t=>t!==type):[...saved,type];updateSaved();toast(existed?'Preference removed':`${type} saved to your preferences`)}));updateSaved();
const currency=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:0}).format(n);let estimate=0;function calculate(){const price=Number($('#car-price').value);$('#down-payment').max=price;if(Number($('#down-payment').value)>price)$('#down-payment').value=price;const down=Number($('#down-payment').value),principal=price-down,months=Number($('#loan-term').value)*12;const raw=Number($('#interest-rate').value);if(!$('#interest-rate').value||!Number.isFinite(raw)||raw<1||raw>30){$('#emi-output').textContent='Enter 1–30%';$('#loan-summary').textContent='Enter a valid annual interest rate.';return}const rate=raw/1200;estimate=principal*rate*Math.pow(1+rate,months)/(Math.pow(1+rate,months)-1);$('#price-output').textContent=currency(price);$('#down-output').textContent=currency(down);$('#emi-output').innerHTML=`${currency(estimate)}<small>/mo</small>`;$('#loan-summary').textContent=`Loan: ${currency(principal)} · Total interest: ${currency(estimate*months-principal)} · ${months} monthly instalments`;}$$('.calculator input,.calculator select').forEach(i=>i.addEventListener('input',calculate));calculate();
const dialog=$('#enquiry-dialog');let enquiryType='';$('#visit-date').min=new Date().toLocaleDateString('en-CA');$$('[data-enquire]').forEach(b=>b.addEventListener('click',()=>{enquiryType=b.dataset.enquire;$('#enquiry-title').textContent=enquiryType;$('#enquiry-preference').value=[filter!=='All'?filter:'',saved.length?'Interested in '+saved.join(', '):'',$('#budget').value!=='Any budget'?$('#budget').value:'',$('#transmission').value!=='Any transmission'?$('#transmission').value:''].filter(Boolean).join(' · ');if(enquiryType.includes('available'))$('#enquiry-preference').value=enquiryType.replace('Explore available ','');$('#date-label').hidden=/Sell|finance/.test(enquiryType);dialog.showModal()}));$$('.dialog-close').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));$$('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));$('#privacy-open').addEventListener('click',()=>$('#privacy-dialog').showModal());$('#enquiry-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);let text=`Hello Car Choice Bhopal!\nI'm ${f.get('name').trim()}.\nI'd like to: ${enquiryType}.`;if(f.get('preference').trim())text+=`\nCar/preferences: ${f.get('preference').trim()}`;if(f.get('date')&&!$('#date-label').hidden)text+=`\nPreferred visit date: ${f.get('date')} (please confirm availability)`;if(f.get('message').trim())text+=`\n${f.get('message').trim()}`;window.open('https://wa.me/919893720977?text='+encodeURIComponent(text),'_blank','noopener,noreferrer');toast('WhatsApp opened. Review and send your enquiry there.');});$('#year').textContent=new Date().getFullYear();
